import{_ as e,o as s,c as t,a0 as i}from"./chunks/framework.BFLrGO6w.js";const u=JSON.parse('{"title":"計算公式說明","description":"","frontmatter":{},"headers":[],"relativePath":"formulas-qa.md","filePath":"formulas-qa.md"}'),o={name:"formulas-qa.md"};function n(p,a,l,d,c,r){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="計算公式說明" tabindex="-1">計算公式說明 <a class="header-anchor" href="#計算公式說明" aria-label="Permalink to &quot;計算公式說明&quot;">​</a></h1><p>這份文件整理本專案所有指標的計算公式、資料來源與已知限制。 想知道「某個數字怎麼算出來的」，先查這裡。</p><p>實作位置以 <code>src/parser/</code> 為準。</p><hr><h2 id="傷害公式" tabindex="-1">傷害公式 <a class="header-anchor" href="#傷害公式" aria-label="Permalink to &quot;傷害公式&quot;">​</a></h2><h3 id="dps" tabindex="-1">DPS <a class="header-anchor" href="#dps" aria-label="Permalink to &quot;DPS&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DPS = 有效傷害 / 戰鬥秒數</span></span>
<span class="line"><span>戰鬥秒數 = pull end - pull start</span></span></code></pre></div><p>實作：<code>report/metrics.ts</code> 的 <code>toActorMetrics</code>。</p><h3 id="有效傷害-overkill-排除" tabindex="-1">有效傷害（overkill 排除） <a class="header-anchor" href="#有效傷害-overkill-排除" aria-label="Permalink to &quot;有效傷害（overkill 排除）&quot;">​</a></h3><p>對齊 FFLogs 的 effective damage 口徑：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有效傷害 = min(原始傷害, 目標當下剩餘 HP)</span></span></code></pre></div><p>超過目標剩餘血量的部分（overkill，殺敵瞬間的溢出傷害）不計入。 目標 HP 來自 log line 的 HP 快照（action line 為 <code>fields[24]/[25]</code>、DoT tick 為 <code>fields[7]/[8]</code>，即被 tick 實體的 HP），缺漏時 fallback 到 HP cache。</p><p><strong>限制</strong>：同一 server frame 的多筆命中共用同一 HP 快照，overkill 是估算而非精確值；快照缺漏或為 0 時不裁切，避免誤刪整筆傷害。</p><p>實作：<code>report/accumulator.ts</code> 的 <code>toEffectiveDamage</code>。</p><h3 id="rdps" tabindex="-1">rDPS* <a class="header-anchor" href="#rdps" aria-label="Permalink to &quot;rDPS*&quot;">​</a></h3><p>與 FFLogs 的 rDPS 概念相同、精度不同，所以標了 <code>*</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rDPS* = (個人有效傷害 - 吃到的外部 raid buff 收益 + 自己提供給隊友的 raid buff 收益) / 戰鬥秒數</span></span></code></pre></div><p>buff 收益估算：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基準傷害 = 實際傷害 / 所有生效 buff 的總倍率</span></span>
<span class="line"><span>額外傷害 = 實際傷害 - 基準傷害</span></span>
<span class="line"><span>多 buff 疊加時，額外傷害依各 buff 的增傷權重 (倍率-1) 拆分給提供者</span></span></code></pre></div><p><strong>與 FFLogs 的差距</strong>：只收錄已驗證的 raid buff metadata；Crit/DH 類 buff（連環計、戰鬥連禱）用保守期望值常數（每 1% crit rate ≈ 0.5% 增傷、每 1% DH rate ≈ 0.25% 增傷），不是依玩家副屬性與事件 crit/DH portion 精算。連環計 metadata 已收錄，但它是套在敵人身上的 target debuff，目前 target-debuff 型 attribution 仍在 <code>doc/fflogs-rdps-validation-plan.md</code> 的 M3 跟進。</p><p>實作：<code>report/rdps.ts</code> 的 <code>estimateRaidBuffContributions</code>。</p><h3 id="dot-的-buff-歸因-snapshot" tabindex="-1">DoT 的 buff 歸因（snapshot） <a class="header-anchor" href="#dot-的-buff-歸因-snapshot" aria-label="Permalink to &quot;DoT 的 buff 歸因（snapshot）&quot;">​</a></h3><p>DoT tick 的 buff 歸因用<strong>狀態施加當下</strong>（snapshot），不是 tick 發生時間——符合 FFXIV 的 DoT snapshot 機制：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DoT tick 的歸因時間 = 該 DoT 狀態最後一次施加的時間（snapshotOffsetSeconds）</span></span>
<span class="line"><span>直接傷害的歸因時間 = 事件發生時間</span></span></code></pre></div><p>所以在 raid buff 視窗內上的 DoT，buff 結束後的 tick 仍算進 buff 貢獻。</p><p><strong>限制</strong>：合併 tick（effectId 0）用「同來源、同目標」的作用中狀態回推，可能配到同來源的非 DoT debuff（如牽制），owner 正確但 snapshot 時間可能取到鄰近狀態。</p><p>實作：<code>report/accumulator.ts</code>（addTickReportEvent）＋ <code>report/rdps.ts</code>。</p><h3 id="boss-add-傷害分類" tabindex="-1">Boss / add 傷害分類 <a class="header-anchor" href="#boss-add-傷害分類" aria-label="Permalink to &quot;Boss / add 傷害分類&quot;">​</a></h3><p>沒有 encounter 資料庫，用 HP heuristic：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>boss 候選 = 目標最大 HP ≥ 玩家最大 HP × 8</span></span></code></pre></div><p>再依 primary target、BNpc 資訊細分 boss / add / object / pet。分類結果影響 <code>bossDamage</code> / <code>addDamage</code> 等統計，不影響總傷害。</p><p>實作：<code>targetClassification.ts</code>、<code>pull/rules.ts</code> 的 <code>isPrimaryTargetCandidate</code>。</p><hr><h2 id="crit-direct-hit" tabindex="-1">Crit / Direct Hit <a class="header-anchor" href="#crit-direct-hit" aria-label="Permalink to &quot;Crit / Direct Hit&quot;">​</a></h2><h3 id="crit-dh-cdh" tabindex="-1">Crit / DH / CDH <a class="header-anchor" href="#crit-dh-cdh" aria-label="Permalink to &quot;Crit / DH / CDH&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Crit% = crit hits / hits</span></span>
<span class="line"><span>DH%   = direct hits / hits</span></span>
<span class="line"><span>CDH%  = 同時爆擊且直擊的 hits / hits</span></span></code></pre></div><p>crit/DH 從 action effect flags 讀取（bit <code>0x2000</code> = crit、<code>0x4000</code> = direct hit）。</p><p><strong>限制</strong>：DoT tick（line 24）沒有 flags，<strong>計入分母但一律視為非爆擊</strong>，所以 DoT 重職業的顯示值會比實際爆擊率低。</p><p>實作：<code>actionEffect.ts</code>（flags 解析）、<code>report/metrics.ts</code>（比率計算）。</p><hr><h2 id="治療公式" tabindex="-1">治療公式 <a class="header-anchor" href="#治療公式" aria-label="Permalink to &quot;治療公式&quot;">​</a></h2><h3 id="hps-有效治療" tabindex="-1">HPS（有效治療） <a class="header-anchor" href="#hps-有效治療" aria-label="Permalink to &quot;HPS（有效治療）&quot;">​</a></h3><p>表上的 HPS 就是 effective HPS（eHPS），<strong>已排除過量治療</strong>，與 FFLogs 的「HPS」同口徑：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HPS = 有效治療 / 戰鬥秒數</span></span>
<span class="line"><span>有效治療 = min(原始治療量, 目標最大 HP - 目標當前 HP)</span></span></code></pre></div><p>包含 overheal 的版本叫 <strong>raw HPS</strong>（表上的「原始治療」欄位除以時間）。</p><p><strong>限制</strong>：</p><ul><li>戰鬥初期 HP cache 未建立時，fallback 把原始治療全算有效 → 短 pull 的 HPS 略偏高。</li><li>護盾（shield/absorb）尚未解析，賢者/學者的盾量不計入有效治療。</li></ul><p>實作：<code>report/accumulator.ts</code> 的 <code>estimateEffectiveHealing</code>。</p><h3 id="過量治療-overheal" tabindex="-1">過量治療（Overheal） <a class="header-anchor" href="#過量治療-overheal" aria-label="Permalink to &quot;過量治療（Overheal）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>過度治療 = 原始治療 - 有效治療</span></span>
<span class="line"><span>過治% = 過度治療 / 原始治療</span></span></code></pre></div><hr><h2 id="技能施放" tabindex="-1">技能施放 <a class="header-anchor" href="#技能施放" aria-label="Permalink to &quot;技能施放&quot;">​</a></h2><h3 id="casts-cpm" tabindex="-1">Casts / CPM <a class="header-anchor" href="#casts-cpm" aria-label="Permalink to &quot;Casts / CPM&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Casts = 玩家 action 次數（含純 buff、utility、落空的施放）</span></span>
<span class="line"><span>CPM = Casts / (戰鬥秒數 / 60)</span></span></code></pre></div><p>排除：自動攻擊、DoT/HoT tick 本身。 AOE 多目標用 <code>timestamp + player + ability</code> 去重成一次施放。</p><p>實作：<code>report/accumulator.ts</code> 的 <code>addPlayerCastEvent</code>。</p><h3 id="gcd-使用率" tabindex="-1">GCD 使用率 <a class="header-anchor" href="#gcd-使用率" aria-label="Permalink to &quot;GCD 使用率&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每次已知 GCD 技能施放 → 視為一段 [施放時間, 施放時間 + recast] 的鎖定區間</span></span>
<span class="line"><span>GCD uptime% = 合併重疊區間後的總長度 / 戰鬥秒數</span></span></code></pre></div><p>只有 ability metadata 收錄的 GCD 技能會納入（recast 預設 2.5s，部分技能有特別值），未知技能不硬算。</p><p>實作：<code>pullSummary.ts</code> 的 <code>getGcdMetrics</code>。</p><hr><h2 id="威力估算" tabindex="-1">威力估算 <a class="header-anchor" href="#威力估算" aria-label="Permalink to &quot;威力估算&quot;">​</a></h2><h3 id="威力-potency-來源" tabindex="-1">威力（potency）來源 <a class="header-anchor" href="#威力-potency-來源" aria-label="Permalink to &quot;威力（potency）來源&quot;">​</a></h3><ol><li>優先用 XIVAPI action metadata 的 potency（含 description 解析）。</li><li>缺 metadata 的傷害事件，用同場次已知事件的比例推估：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>damagePerPotency = 已知事件總傷害 / 已知事件總威力</span></span>
<span class="line"><span>推估威力 = 該事件傷害 / damagePerPotency</span></span></code></pre></div><p>UI 進度條：深綠 = 直接 metadata、淺綠 = 傷害比例推估。</p><p><strong>限制</strong>：buff 期間傷害偏高會讓推估威力略偏高；傷害為 0 的事件無法推估。</p><p>實作：<code>analysis/rotationAnalyzer.ts</code> 的 <code>analyzePotency</code>。</p><h3 id="buff-期間威力-覆蓋率" tabindex="-1">Buff 期間威力 / 覆蓋率 <a class="header-anchor" href="#buff-期間威力-覆蓋率" aria-label="Permalink to &quot;Buff 期間威力 / 覆蓋率&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Buff 期間威力 = 落在任一已收錄 buff 視窗內的事件威力總和</span></span>
<span class="line"><span>Buff 覆蓋率 = Buff 期間威力 / 總威力</span></span></code></pre></div><p>buff 視窗只計已收錄的 raid buff / personal buff（3–45 秒的短效增益），排除坦姿、食物等長效狀態。</p><hr><h2 id="pull-切分與階段" tabindex="-1">Pull 切分與階段 <a class="header-anchor" href="#pull-切分與階段" aria-label="Permalink to &quot;Pull 切分與階段&quot;">​</a></h2><h3 id="pull-切分" tabindex="-1">Pull 切分 <a class="header-anchor" href="#pull-切分" aria-label="Permalink to &quot;Pull 切分&quot;">​</a></h3><p>三層 inactivity 門檻（預設 gap 45 秒）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>滅團中（多數玩家死亡且未復活行動）→ 20 秒安靜就切</span></span>
<span class="line"><span>戰鬥中（主目標存活、未滅團）      → 90 秒（容許過場動畫）</span></span>
<span class="line"><span>其他                              → 45 秒</span></span></code></pre></div><p>輔助規則：</p><ul><li><strong>滅團偵測</strong>：玩家死亡（line 25，含環境殺 E0000000）加入死亡名單；之後施放技能（21/22）視為已復活移除。死亡中人數 ≥ max(4, 玩家數 × 0.75) 判定滅團。</li><li><strong>target swap 關閉</strong>：只有主目標「已死亡」後出現新的大血量目標才切新 pull；主目標活著時的新大目標視為同場戰鬥的階段角色或 add。</li><li><strong>主目標升級</strong>：血量 ≥ 現任主目標 1.2 倍的新形態會接手主目標身分（例如究極武器最終階段），pull 名稱才會對到玩家認知的 boss。</li></ul><p>實作：<code>pull/rules.ts</code>、<code>detectPulls.ts</code>。</p><h3 id="階段切分" tabindex="-1">階段切分 <a class="header-anchor" href="#階段切分" aria-label="Permalink to &quot;階段切分&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每個大型目標（boss 級 HP）「首次被玩家攻擊」記為一個階段起點</span></span>
<span class="line"><span>階段結束 = 下一個階段的開始（最後一段到 pull 結束）</span></span></code></pre></div><p>只認玩家主動攻擊（21/22）——大血量 add 攻擊玩家不算接戰，避免妙翅、爆破岩石這類 add 被誤標成階段。同名目標重複出現（如亂流階段）不會切出新階段。</p><p>每個階段產生完整報表（<code>phaseReports[]</code>）：所有表格從逐筆事件重算，與整場用同一套公式（DPS、rDPS*、Crit、治療、承傷、死亡、Casts、GCD uptime）。</p><p><strong>限制</strong>：階段時間窗以「下一個 boss 首次被攻擊」為界，過場與中間 add 潮（亂流）會算在前一階段內。</p><p>實作：<code>detectPulls.ts</code> 的 <code>trackPhaseMarker</code>、<code>pullSummary.ts</code> 的 <code>toPhaseReport</code>。</p><h3 id="kill-wipe-判定" tabindex="-1">Kill / Wipe 判定 <a class="header-anchor" href="#kill-wipe-判定" aria-label="Permalink to &quot;Kill / Wipe 判定&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kill：勝利系統訊息（寶箱出現）或 primary target 死亡</span></span>
<span class="line"><span>wipe：死亡玩家名數 ≥ max(4, 玩家數 × 0.75)</span></span>
<span class="line"><span>其餘：unknown</span></span></code></pre></div><p>階段報表只有最後一個階段繼承整場結果（boss 在該階段倒下）。</p><p>實作：<code>pullSummary.ts</code> 的 <code>inferResult</code>。</p><hr><h2 id="做不到-不做的" tabindex="-1">做不到 / 不做的 <a class="header-anchor" href="#做不到-不做的" aria-label="Permalink to &quot;做不到 / 不做的&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指標</th><th>原因</th></tr></thead><tbody><tr><td>Parse percentile（色字）</td><td>需要 FFLogs 全站同職業/同副本分布資料庫</td></tr><tr><td>aDPS</td><td>需要 FFLogs 官方的 per-job padding buff 規則</td></tr><tr><td>精確 mitigation（減傷量）</td><td>需要技能原始威力或未減傷樣本</td></tr><tr><td>護盾量（absorb）</td><td>shield effect 尚未解析（排在 P4）</td></tr><tr><td>機制分析</td><td>需要 encounter metadata（已移除骨架，見 git 歷史）</td></tr></tbody></table><hr><h2 id="更新原則" tabindex="-1">更新原則 <a class="header-anchor" href="#更新原則" aria-label="Permalink to &quot;更新原則&quot;">​</a></h2><p>改了任何公式：</p><ol><li>對應更新這份文件。</li><li>bump <code>parserVersion</code>（<code>src/web/storage/logStore.ts</code>），讓 IndexedDB 自動 reparse。</li><li><code>npm run parse</code> 重新產生 public data。</li><li>版本歷史記在 <code>local-parser-notes.md</code>。</li></ol>`,96)])])}const b=e(o,[["render",n]]);export{u as __pageData,b as default};
